mapper.select:
with insite_work_order as ( select 'Insite'::text as issue_type,
from v2_work_order w LEFT JOIN asset_info a ON w.asset_id = a.id LEFT JOIN v2_service_request r ON w.sr_id = r.id left join user_org uo ON uo.org_uid IN (a.tenant_uid, a.institution_uid, a.hospital_uid, a.site_uid, a.clinical_dept_uid,r.from_dept_uid) where a.uid is not null AND a.is_valid AND NOT a.is_deleted
), mvs_work_order as ( select 'MVS'::text as issue_type,
from v2_work_order w left join v2_service_request r on w.sr_id = r.ID left join mvs_ib_mapping m1 ON w.asset_uid = m1.mvs_ib_uid or w.asset_uid=m1.e_home_ib_uid left join asset_info a ON m1.ib_uid = a.uid left join user_org uo ON uo.org_uid IN (a.tenant_uid, a.institution_uid, a.hospital_uid, a.site_uid, a.clinical_dept_uid,r.from_dept_uid) WHERE a.uid is not null AND a.is_valid AND NOT a.is_deleted AND (m1.mvs_ib_uid IS NOT NULL OR m1.e_home_ib_uid IS NOT NULL)
), unified_work_order as ( select * from insite_work_order UNION ALL select * from mvs_work_order ) select * from unified_work_order ORDER BY sr_request_time DESC
LIMIT #{pageSize} OFFSET #{offset}

with insite_work_order as ( select w.id from v2_work_order w LEFT JOIN asset_info a ON w.asset_id = a.id LEFT JOIN v2_service_request r ON w.sr_id = r.id left join user_org uo ON uo.org_uid IN (a.tenant_uid, a.institution_uid, a.hospital_uid, a.site_uid, a.clinical_dept_uid,r.from_dept_uid) where a.uid is not null AND a.is_valid AND NOT a.is_deleted
), mvs_work_order as ( select w.id FROM v2_work_order w left join v2_service_request r on w.sr_id = r.ID left join mvs_ib_mapping m1 ON w.asset_uid = m1.mvs_ib_uid or w.asset_uid=m1.e_home_ib_uid left join asset_info a ON m1.ib_uid = a.uid left join user_org uo ON uo.org_uid IN (a.tenant_uid, a.institution_uid, a.hospital_uid, a.site_uid, a.clinical_dept_uid,r.from_dept_uid) WHERE a.uid is not null AND a.is_valid AND NOT a.is_deleted AND (m1.mvs_ib_uid IS NOT NULL OR m1.e_home_ib_uid IS NOT NULL)
) select count(*) from ( select id from insite_work_order UNION ALL select id from mvs_work_order ) t
